{{(() => {
  const selected = appsmith.store.selected_vendor_group || {};

  const groupName =
    selected.GROUP_NAME ||
    "No RFQ group selected";

  const referenceId =
    selected.referenceId ||
    selected.groupId ||
    selected.RFQ_GROUP_ID ||
    "";

  const status =
    selected.status ||
    selected.STATUS ||
    "RFQ DATA PENDING";

  const rfqPath =
    selected.rfqPath ||
    selected.RFQ_PATH ||
    selected.previewUrl ||
    "";

  return {
    selected: {
      ...selected,
      documentTitle:
        referenceId
          ? `${groupName} • ${referenceId}`
          : groupName,
      sourcePath:
        rfqPath ||
        "RFQ document is not available yet",
      status
    }
  };
})()}}

