:root {
  --ink: #0f172a;
  --muted: #64748b;
  --border: #dbe4ef;
  --blue: #2563eb;
  --green: #16a34a;
}
html, body, #root {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  box-sizing: border-box;
  background: transparent;
  font-family: "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
*, *::before, *::after { box-sizing: border-box; }
.toolbar {
  width: 100%;
  height: 100%;
  min-height: 58px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 9px 14px;
  background: #ffffff;
  border: 1px solid var(--border);
  border-bottom: 0;
  border-radius: 7px 7px 0 0;
}
.icon-wrap {
  width: 27px;
  height: 27px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  background: linear-gradient(135deg, #ede9fe, #dbeafe);
  color: #4f46e5;
}
.copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}
.title-line {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--ink);
  font-size: 11px;
  line-height: 1.2;
  font-weight: 800;
}
.online {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 2px #dcfce7;
  flex: 0 0 auto;
}
.path {
  color: var(--muted);
  font-size: 9px;
  line-height: 1.3;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.actions {
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 0 0 auto;
}
.doc-button {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  background: #ffffff;
  color: #2563eb;
  cursor: default;
}
.readonly {
  padding: 5px 9px;
  border-radius: 4px;
  background: #e9eef5;
  color: #475569;
  font-size: 8px;
  line-height: 1;
  font-weight: 850;
  letter-spacing: .35px;
  white-space: nowrap;
}

