    strokeLinecap: 'round',
    strokeLinejoin: 'round'
  },
  React.createElement('path', { d: 'M4 7a4 4 0 0 1 4-4h8a4 4 0 0 1 4 4' }),
  React.createElement('path', { d: 'M4 7h16v10a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4z' }),
  React.createElement('path', { d: 'M8 11h8' })
);

const DocumentIcon = () => React.createElement(
  'svg',
  {
    width: 15,
    height: 15,
    viewBox: '0 0 24 24',
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 2,
    strokeLinecap: 'round',
    strokeLinejoin: 'round'
  },
  React.createElement('path', { d: 'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z' }),
  React.createElement('polyline', { points: '14 2 14 8 20 8' })
);

function PreviewHeaderComponent() {
  const [model, setModel] = useState(() => parseModel(window.appsmith?.model));

  useEffect(() => {
    window.appsmith?.onModelChange?.((next) => setModel(parseModel(next)));
  }, []);

  const selected = model.selected || {};

  return React.createElement(
    'div',
    { className: 'toolbar' },
    React.createElement('div', { className: 'icon-wrap' }, React.createElement(StorageIcon, null)),
    React.createElement(
      'div',
      { className: 'copy' },
      React.createElement(
        'div',
        { className: 'title-line' },
        React.createElement(
          'div',
          { className: 'title' },
          selected.documentTitle || 'SharePoint Linked Storage'
        ),
        React.createElement('span', { className: 'online', title: 'Online' })
      ),
      React.createElement(
        'div',
        { className: 'path' },
        selected.sourcePath || 'SharePoint/Procurement/Vendor-Recommendations'
      )
    ),
    React.createElement(
      'div',
      { className: 'actions' },
      React.createElement('div', { className: 'doc-button', 'aria-hidden': true }, React.createElement(DocumentIcon, null)),
      React.createElement('div', { className: 'readonly' }, selected.status || 'READ-ONLY')
    )
  );
}

appsmith.onReady(() => {
  ReactDOM.render(
    React.createElement(PreviewHeaderComponent, null),
    document.getElementById('root')
  );
});

